package httpsmanager

const confirmPage = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Confirm HTTPS · CloudMateHub</title></head><body style="font:17px system-ui;max-width:680px;margin:10vh auto;padding:24px;background:#0d1921;color:#dce9ee"><h1>Keep this HTTPS configuration?</h1><p>Check that your browser trusts this certificate and shows the expected address. If it does not, close this page and the previous configuration will return automatically.</p><button id="keep">Keep HTTPS</button> <a href="DASHBOARD_URL">Open dashboard</a><p id="result" role="status"></p><script>
const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);
document.querySelector('#keep').onclick=async()=>{const r=await fetch('/api/https/confirm',{method:'POST',headers:{'X-Activation-Token':token}});const d=await r.json();document.querySelector('#result').textContent=r.ok?'HTTPS confirmed. The previous configuration is retained as a restore point.':d.error;document.querySelector('#keep').disabled=r.ok;};
</script></body></html>`

const recoveryPage = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>HTTPS Recovery · CloudMateHub</title></head><body style="font:16px system-ui;max-width:780px;margin:5vh auto;padding:24px;background:#0d1921;color:#dce9ee"><h1>CloudMateHub HTTPS recovery</h1><p>This server-local page works independently of the application gateway. Reach it on this server or through an SSH tunnel. It changes only HTTPS configuration.</p><p>Run <code>./deployments/cloudmatehub recovery</code> on this server to obtain your private recovery link. Keep it secret.</p><p><label>Recovery access key <input id="access" type="password" autocomplete="off"></label> <button id="unlock">Unlock recovery</button></p><p>Private CA certificates require browsers and device agents to trust that CA before activation.</p><p><label>Certificate and intermediate chain (PEM)<br><input id="cert" type="file" accept=".pem,.crt,.cer"></label></p><p><label>Private key (PEM)<br><input id="key" type="file" accept=".pem,.key"></label></p><p><label>Private CA bundle (optional)<br><input id="ca" type="file" accept=".pem,.crt"></label></p><button id="stage">Validate certificate</button> <button id="activate" disabled>Test and activate for 60 seconds</button> <button id="restore">Restore previous / cancel activation</button><p><label>Saved validated certificates <select id="saved"><option value="">Select a certificate</option></select></label></p><p id="message" role="status"></p><pre id="status" style="white-space:pre-wrap"></pre><script>
const csrf='CSRF_TOKEN';let access=location.hash.slice(1);history.replaceState(null,'',location.pathname);let candidate='';const msg=document.querySelector('#message');
async function api(path,body){const r=await fetch('/api/https/'+path,{method:body?'POST':'GET',headers:{'X-Recovery-Token':csrf,'X-Recovery-Key':access,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
async function refresh(){try{const d=await api('status');const active=d.certificates.find(c=>c.id===d.active);document.querySelector('#status').textContent='Host: '+d.host+'\nHTTPS: '+(active?'Active; expires '+new Date(active.expires).toLocaleDateString()+'; '+active.trust:'Not confirmed yet')+'\n'+(d.pending?'Candidate waiting until '+new Date(d.deadline).toLocaleTimeString():'No activation pending')+'\nRestore points: '+d.certificates.length;const select=document.querySelector('#saved');select.replaceChildren(new Option('Select a certificate',''));for(const c of d.certificates.filter(c=>c.id!==d.active)){select.add(new Option(new Date(c.expires).toLocaleDateString()+' · '+c.trust+' · '+c.id.slice(0,8),c.id));}select.value=candidate;}catch(e){msg.textContent=e.message;}}
document.querySelector('#unlock').onclick=()=>{access=document.querySelector('#access').value;document.querySelector('#access').value='';refresh();};
document.querySelector('#saved').onchange=(e)=>{candidate=e.target.value;document.querySelector('#activate').disabled=!candidate;};
document.querySelector('#stage').onclick=async()=>{try{const c=document.querySelector('#cert').files[0],k=document.querySelector('#key').files[0],ca=document.querySelector('#ca').files[0];if(!c||!k)throw Error('Select a certificate and its private key.');const d=await api('candidates',{certificate:await c.text(),private_key:await k.text(),ca:ca?await ca.text():''});candidate=d.id;document.querySelector('#key').value='';document.querySelector('#activate').disabled=false;msg.textContent='Validated. Trust: '+d.trust+'. Expires: '+d.expires;refresh();}catch(e){msg.textContent=e.message;}};
document.querySelector('#activate').onclick=async()=>{try{const d=await api('activate',{id:candidate});msg.textContent='Open the HTTPS confirmation page within '+d.seconds+' seconds. Without confirmation, activation rolls back.';const a=document.createElement('a');a.href=d.confirmation_url;a.textContent='Open HTTPS confirmation';a.target='_blank';a.rel='noopener noreferrer';msg.append(' ',a);refresh();}catch(e){msg.textContent=e.message;}};
document.querySelector('#restore').onclick=async()=>{try{await api('restore',{});msg.textContent='Previous configuration restored.';refresh();}catch(e){msg.textContent=e.message;}};refresh();setInterval(refresh,5000);
</script></body></html>`
